    is_pursuer = ("pursuer" in role) or ("chaser" in role) or ("catcher" in role)
    is_evader = ("evader" in role) or ("runner" in role) or ("escape" in role)
    if not (is_pursuer or is_evader):
        is_pursuer = True
    if not is_pursuer:
        is_evader = True

    resources = observation.get("resources") or []
    res_pts = []
